const rawBody = $json.body ?? $json;
const message = (rawBody.message ?? rawBody.text ?? '').toString().trim();
const userId = (rawBody.userId ?? rawBody.user ?? 'anonymous').toString().trim();
const sessionId = (rawBody.sessionId ?? rawBody.conversationId ?? userId).toString().trim();
const userContext = rawBody.userContext ?? {};
const modo = (rawBody.modo ?? 'auto').toString().toLowerCase().trim();
const imageAttachments = Array.isArray(rawBody.imageAttachments)
  ? rawBody.imageAttachments
      .filter((item) => item && (item.dataUrl || item.imageUrl || item.url || item.signedUrl) && item.type && item.type.startsWith('image/'))
      .slice(0, 4)
      .map((item) => {
        const imageUrl = (item.dataUrl || item.imageUrl || item.url || item.signedUrl || '').toString();
        return {
          name: (item.name ?? 'imagem').toString(),
          type: (item.type ?? 'image/*').toString(),
          size: Number(item.size ?? 0),
          signedUrl: (item.signedUrl || item.imageUrl || item.url || imageUrl).toString(),
          imageUrl,
          url: imageUrl,
          dataUrl: item.dataUrl ? item.dataUrl.toString() : undefined,
        };
      })
  : [];

if (!message && imageAttachments.length === 0) return [{ ok: false, error: "Missing 'message'" }];

const memoryKey = userId + '__' + sessionId;
return [{
  ok: true,
  message,
  userId,
  sessionId,
  memoryKey,
  userContext,
  modo,
  imageAttachments,
  receivedAt: new Date().toISOString(),
}];

