const routedInput = $('Fast Router').item.json;
const classifierResponse = $json;

let cls = routedInput.fastRoute?.classifier || {};
if (!routedInput.fastRoute?.skipClassifier) {
  try {
    const raw = classifierResponse.choices[0].message.content.trim();
    const fence = String.fromCharCode(96, 96, 96);
    const clean = raw.replace(new RegExp(fence + 'json|' + fence, 'g'), '').trim();
    cls = JSON.parse(clean);
  } catch {
    cls = routedInput.fastRoute?.classifier || {
      tipo:'geral', area:'geral', complexidade:'media', usarBase:false,
      usarMemoria:true, modo_sugerido:'corvus', ehSimulacao:false, ehDecisao:false
    };
  }
}

const validModes = ['corvus','fenrir','cipher','conselho','simulacao'];
const modoManual = routedInput.modo;
let resolvedMode = validModes.includes(modoManual) ? modoManual : (cls.modo_sugerido || 'corvus');
if (cls.ehSimulacao && modoManual === 'auto') resolvedMode = 'simulacao';
if (resolvedMode === 'conselho' && cls.complexidade !== 'alta') resolvedMode = 'cipher';

const topKMap = { baixa: 3, media: 5, alta: 8 };
const topK = topKMap[cls.complexidade] || 5;
const baseConf = { baixa: 0.92, media: 0.78, alta: 0.65 };
const typeMod = { pergunta:0.05, decisao:-0.05, simulacao:-0.10, ideia:-0.08, criativo:-0.06, problema:0, geral:0 };
const fastConfidence = routedInput.fastRoute?.confidence || 0;
const estimatedConfidence = Math.min(0.99, Math.max(0.40,
  fastConfidence || ((baseConf[cls.complexidade] || 0.75) + (typeMod[cls.tipo] || 0))
)).toFixed(2);

const userContext = routedInput.userContext || {};
const userCtxString = [
  'Nome: ' + (userContext.nome || 'Desconhecido'),
  'Cargo: ' + (userContext.cargo || '-'),
  'Sigla: ' + (userContext.sigla || '-'),
  'Tipo: ' + (userContext.tipo || 'convidado')
].join(' | ');

const visualContext = routedInput.visualContext || null;
const visualCtxString = visualContext
  ? [
      'OCR: ' + (visualContext.ocrText || 'sem texto detectado'),
      'Descricao: ' + (visualContext.description || ''),
      'Itens: ' + ((visualContext.relevantItems || []).join(', ') || '-'),
      'Limitacoes: ' + (visualContext.limitations || '-')
    ].join('\n')
  : '';

return [{
  message: routedInput.message,
  userId: routedInput.userId,
  sessionId: routedInput.sessionId,
  memoryKey: routedInput.memoryKey,
  userContext,
  userCtxString,
  visualContext,
  visualCtxString,
  usedVision: Boolean(visualContext),
  imageAttachments: routedInput.imageAttachments || [],
  receivedAt: routedInput.receivedAt,
  orchestrator: {
    tipo: cls.tipo || 'geral', area: cls.area || 'geral',
    complexidade: cls.complexidade || 'media',
    usarBase: cls.usarBase !== false,
    usarMemoria: cls.usarMemoria !== false,
    modoSugerido: cls.modo_sugerido || 'corvus',
    ehSimulacao: cls.ehSimulacao === true,
    ehDecisao: cls.ehDecisao === true,
    requestedMode: routedInput.modo,
    resolvedMode,
    topK,
    fastPath: routedInput.fastRoute?.skipClassifier === true,
    estimatedConfidence: parseFloat(estimatedConfidence)
  }
}];

const agentOutput = $input.first().json;
let oc = {};
try { oc = agentOutput.orchestrator || JSON.parse(agentOutput.orchestratorData || '{}'); } catch {}
if (oc.ehDecisao === true) {
  console.log('[corvus:decision]', JSON.stringify({
    msg: (agentOutput.message||'').substring(0,200),
    tipo: oc.tipo, area: oc.area, modo: oc.resolvedMode, ts: new Date().toISOString()
  }));
}
return [agentOutput];

const agentOutput = $input.first().json;

let oc = {};
try {
  oc = agentOutput.orchestrator || JSON.parse(agentOutput.orchestratorData || '{}');
} catch {}

const resolvedMode = agentOutput.resolvedMode || oc.resolvedMode || 'corvus';
const modeLabels = {
  corvus:'Corvus - Institucional', fenrir:'Fenrir - Criativo',
  cipher:'Cipher - Estrategico', conselho:'Conselho - Perspectiva Tripla',
  simulacao:'Simulacao - Analise de Cenarios'
};

const base = oc.estimatedConfidence || 0.75;
const ragBonus = oc.usarBase ? 0.05 : 0;
const cxPenalty = oc.complexidade === 'alta' ? -0.08 : (oc.complexidade === 'baixa' ? 0.04 : 0);
const confidence = Math.min(0.99, Math.max(0.40, base + ragBonus + cxPenalty));
const visualContext = agentOutput.visualContext || null;
const usedVision = Boolean(agentOutput.usedVision || visualContext);

const suggestionsMap = {
  decisao: ['Simular cenario', 'Ver alternativas', 'Analisar riscos com Cipher'],
  problema: ['Analisar com Cipher', 'Simular solucao', 'Consultar Conselho'],
  ideia: ['Expandir com Fenrir', 'Analisar viabilidade', 'Simular impacto'],
  simulacao: ['Analisar decisao', 'Consultar Conselho', 'Salvar como decisao'],
  conselho: ['Aprofundar com Cipher', 'Expandir com Fenrir', 'Simular cenario'],
  geral: ['Gerar ideia', 'Analisar decisao', 'Simular cenario']
};
const suggestions = suggestionsMap[oc.tipo] || suggestionsMap.geral;

function cleanText(value) {
  return (value || '').toString().replace(/\s+/g, ' ').trim();
}
function makeTags() {
  const tags = new Set();
  if (oc.area && oc.area !== 'geral') tags.add(oc.area);
  if (oc.tipo && oc.tipo !== 'geral') tags.add(oc.tipo);
  if (resolvedMode && resolvedMode !== 'corvus') tags.add(resolvedMode);
  if (usedVision) tags.add('imagem');
  if (oc.usarBase) tags.add('msy');
  return Array.from(tags).slice(0, 5);
}
function makeNextActions(reply) {
  const lines = reply.split('\n').map(cleanText).filter(Boolean);
  const actionLines = lines.filter((line) => /^(\d+\.|-|\*)?\s*(definir|validar|revisar|criar|enviar|priorizar|analisar|executar|documentar|alinhar)/i.test(line));
  return (actionLines.length ? actionLines : suggestions).slice(0, 4);
}

if (agentOutput.consiliumPayload?.isConselho) {
  const consiliumText = agentOutput.consiliumPayload.blocks.map((block) => block.label + ': ' + block.reply).join('\n');
  return {
    json: {
      ok: true,
      reply: consiliumText,
      consilium: agentOutput.consiliumPayload.blocks,
      meta: {
        agent:'Corvus 3.2 Beta', model:'gpt-4o', mode:'conselho',
        modeLabel: modeLabels.conselho,
        complexity: oc.complexidade || 'media', usedRAG: oc.usarBase || false,
        usedVision, visualSummary: visualContext?.description || '',
        confidence: parseFloat(confidence.toFixed(2)), tipo: oc.tipo || 'geral',
        summaryCandidate: cleanText(consiliumText).slice(0, 360),
        tags: makeTags(),
        nextActions: makeNextActions(consiliumText),
        decisionCandidate: oc.ehDecisao === true,
        timestamp: new Date().toISOString(), suggestions
      }
    }
  };
}

const reply = (
  agentOutput.output ?? agentOutput.text ?? agentOutput.response ??
  agentOutput.message ?? (agentOutput.choices && agentOutput.choices[0]?.message?.content) ?? ''
).toString().trim();

if (!reply) {
  return { json: { ok: false, error: 'Agente nao retornou resposta.', code: 'agent_empty_response' } };
}

return {
  json: {
    ok: true,
    reply,
    consilium: null,
    meta: {
      agent:'Corvus 3.2 Beta', model:'gpt-4o', mode: resolvedMode,
      modeLabel: modeLabels[resolvedMode] ?? resolvedMode,
      complexity: oc.complexidade || 'media', usedRAG: oc.usarBase === true,
      usedVision, visualSummary: visualContext?.description || '',
      confidence: parseFloat(confidence.toFixed(2)), tipo: oc.tipo || 'geral',
      summaryCandidate: cleanText(reply).slice(0, 360),
      tags: makeTags(),
      nextActions: makeNextActions(reply),
      decisionCandidate: oc.ehDecisao === true,
      timestamp: new Date().toISOString(), suggestions
    }
  }
};

